  strokes('k10-10', 'k10', '{画数|かくすう}②', 0.8, '人2 水4 正5 生5 青8 夕3 石5 赤7 千3 川3 先6 早6 草9 足7 村7 大3 男7 竹6 中4 虫6 町7 天4 田5 土3 二2 日4 入2 年6 白5 八2 百6 文4 木4 本5 名6 目5 立5 力2 林8 六4');
